function fmtDate(iso){var a=iso.split('-');return a[2]+'.'+a[1]+'.'+a[0]}
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
var filter='all',selId=null,hovId=null;
var ICON={'Krach':'M3 6l6 6 4-4 8 9M21 11v6h-6','Szczyt':'M3 19l7-12 4 6 2-3 5 9z','Upadek':'M12 4l9 16H3zM12 10v5M12 17.6v.4','Regulacje':'M4 9l8-5 8 5M6 9v9M10 9v9M14 9v9M18 9v9M3 20h18',
 'Halving':'M12 3a9 9 0 1 0 0 18a9 9 0 1 0 0-18M12 3v18','Kamień milowy':'M6 21V4M6 5h11l-2 4 2 4H6','Cykl':'M20 11a8 8 0 0 0-14-4M4 4v4h4M4 13a8 8 0 0 0 14 4M20 20v-4h-4',
 'Ruch kapitału':'M4 8h13l-3-3M20 16H7l3 3','Hack':'M12 3l8 4v5c0 5-3.5 8-8 9-4.5-1-8-4-8-9V7zM9.5 12l2 2 3.5-4','ETF':'M4 20V10M10 20V4M16 20v-7M22 20H2','Polityka':'M5 21V4h12l-2 4 2 4H5','Cykl BTC':'M12 3a9 9 0 1 0 0 18a9 9 0 1 0 0-18M12 3v18','Legenda':'M12 3l2.6 5.6 6 .8-4.4 4.2 1.1 6L12 16.8l-5.3 2.8 1.1-6L3.4 9.4l6-.8z','Strata':'M7 21V10a5 5 0 0 1 10 0v11M4 21h16M12 9v6M9.5 11.5h5','Zakup':'M12 5v14M5 12h14','Sprzedaż':'M5 12h14','Kluczowy moment':'M15 5a4 4 0 1 1 0 8a4 4 0 1 1 0-8M12.2 11.8L4 20M7 17l2 2M5 19l2 2','Lekcja':'M12 3l2.6 5.6 6 .8-4.4 4.2 1.1 6L12 16.8l-5.3 2.8 1.1-6L3.4 9.4l6-.8z','Inne':'M5 12h.01M12 12h.01M19 12h.01'};
