  var rl=railW();mo.style.marginLeft=-(wr0.left-rl)+'px';mo.style.marginRight=-(cw0-wr0.right)+'px';mo.style.setProperty('--gut',Math.max(0,wr0.left-rl)+'px');
  var r=stage.getBoundingClientRect();W=r.width;H=r.height;dpr=Math.min(2,window.devicePixelRatio||1);
  cv.width=Math.round(W*dpr);cv.height=Math.round(H*dpr);
  var mr=mini.getBoundingClientRect();mini.width=Math.round(mr.width*dpr);mini.height=Math.round(mr.height*dpr);
  var small=W<620;SLOT=small?10:13;CW=small?170:204;CH=small?34:36;AXW=small?52:66;PADR=Math.max(small?150:210,Math.round(W*.14));   /* (22) room right of "Teraz" for its label, the launch of the impulse and the price scale - about 14% of the width */
