function frontCol(i){for(var q=0;q<FR.length;q++){var d=FR[q].f-i;if(d>=-1&&d<50)return FR[q].col;}return '235,238,244';}
/* ---------- drawing ---------- */
var MON=['sty','lut','mar','kwi','maj','cze','lip','sie','wrz','paź','lis','gru'];
