  FR=[];if(introDone&&!reduced){var tt=(ts-tDone)/1000;for(var q=0;q<2;q++){var t2=tt-q*PERIOD/2;if(t2<0)continue;FR.push({ph:t2%PERIOD,f:(t2%PERIOD)*VEL-8,col:q?'255,122,112':'96,232,176'});}}
  var i0=Math.max(0,Math.floor((camX-PADL)/SLOT)-2),i1=Math.min(N-1,Math.ceil((camX+W-PADL)/SLOT)+2);
  var ph=plotBot-plotTop,i,x,c,k,hN=Math.min(N,Math.floor(head));
  var lo=1e9,hi=0;
  for(i=i0;i<=i1&&i<hN;i++){var vx=xOf(i)-camX;if(vx<0||vx>W-AXW)continue;if(C[i].lo<lo)lo=C[i].lo;if(C[i].hi>hi)hi=C[i].hi;}
  if(hi>0){var a0=Math.log(lo*0.94),a1=Math.log(hi*1.05),mid=(a0+a1)/2,span=Math.max(a1-a0,0.25);a0=mid-span/2;a1=mid+span/2;
    var kk=reduced?1:ez(.07);LN0+=(a0-LN0)*kk;LN1+=(a1-LN1)*kk;}
  function tAt(sx){return T0+((sx+camX-PADL)/SLOT)*WEEK}

