    for(k=1;k<ERAS.length;k++){var ex=xDate(ERAS[k].t)-camX;if(ex<=0||ex>=W)continue;
      var p1=clamp((ex-80)/W,pos,1),p2=clamp((ex+80)/W,p1,1);
      g.addColorStop(p1,'rgb('+ECOL[ERAS[k-1].k]+')');g.addColorStop(p2,'rgb('+ECOL[ERAS[k].k]+')');pos=p2;}
    g.addColorStop(1,'rgb('+ECOL[eraAt(tAt(W)).k]+')');
    ctx.beginPath();ctx.moveTo(xOf(first)-camX,plotBot);
    for(i=first;i<=lastI;i++)ctx.lineTo(xOf(i)-camX,yP(C[i].c));
    ctx.lineTo(xOf(lastI)-camX,plotBot);ctx.closePath();
    ctx.save();ctx.clip();ctx.globalAlpha=.155;ctx.fillStyle=g;ctx.fillRect(0,plotTop-30,W,ph+30);
