  for(var y=Y0;y<=Y1;y++){x=xDate(Date.UTC(y,0,1))-camX;var nx=x+14+(W*0.25-x)*0.2;if(nx>W+10||nx<-fs*2.6)continue;ctx.fillText(String(y),nx,plotBot-6);}

  /* cycle: a quiet bracket on the floor */
