  if(cycOn){ctx.strokeStyle='rgba(233,178,92,.22)';ctx.lineWidth=1;ctx.setLineDash([2,4]);ctx.beginPath();ctx.moveTo(Math.round(cx0)+.5,yP(C[wk(CYC.iso)].c)+10);ctx.lineTo(Math.round(cx0)+.5,plotBot);ctx.stroke();ctx.setLineDash([]);}

