  var w=whale;w.x+=w.v*w.d*dt;if(w.x<-w.L*1.6||w.x>SW+w.L*1.6){whale=null;whaleT=rnd(50,90);return;}
  var L=w.L,y=w.y+Math.sin(skyT*.35+w.p)*7,i;
  for(i=0;i<fish.length;i++){var fdx=fish[i].x-w.x;if(Math.abs(fdx)<L*.7&&Math.abs(fish[i].y-y)<L*.4){fish[i].x+=(fdx>0?1:-1)*70*dt;fish[i].y+=(fish[i].y>y?1:-1)*16*dt;}}
  if(Math.random()<dt*.25)bubbles.push({x:w.x+w.d*L*.28+rnd(-6,6),y:y-L*.1,r:rnd(1,2.6),vy:rnd(16,36),ph:Math.random()*6.28});
