  var L=scene.legends,n=L.length,x0=bbL+bw+30,x1=bbR-rw-30;if(!n||x1-x0<n*46)return;
  var YS=[.6,0,.85,.2,1,.1],P=[],q;for(q=0;q<n;q++)P.push([x0+(x1-x0)*(q+.5)/n,bbY+24+Math.max(0,h-70)*YS[q%6]]);
