  drawWater();if(BGM>1)drawBear();   /* (22) no whales */drawBed();
  if(mapOn&&BGM>1){sctx.save();sctx.translate(0,MDY);drawWorld(dt);sctx.restore();}   /* map view: the map lies over the sea and the bed, not under them */
