        for(j=0;j<34;j++)silt.push({x:c.x+rnd(-1,1)*c.size,y:gy0,vx:rnd(-40,40),vy:-rnd(6,46),l:rnd(.7,1),s:rnd(4,10)});
        for(j=0;j<28;j++){var sd=j%2?1:-1;silt.push({x:c.x+sd*c.size*.6,y:gy0+rnd(-2,4),vx:sd*rnd(50,170),vy:-rnd(0,7),l:rnd(.6,1),s:rnd(3,7)});}
        for(j=0;j<12;j++)silt.push({x:c.x+rnd(-1,1)*c.size*.5,y:gy0,vx:rnd(-90,90),vy:-rnd(60,150),l:1,s:rnd(.8,1.6),peb:1});
        for(j=0;j<5;j++)bubbles.push({x:c.x+rnd(-1,1)*c.size,y:gy0-rnd(0,10),r:rnd(1,2.8),vy:rnd(30,70),ph:Math.random()*6.28});
        for(j=0;j<fish.length;j++)if(Math.abs(fish[j].x-c.x)<220)fish[j].v=(fish[j].x>c.x?1:-1)*Math.abs(fish[j].v);
