/* ---------- loop ---------- */
var lastRead=0,lastHover=-2,lastTs=0,DT=1/60,FS=1;
function ez(k){return 1-Math.pow(1-k,FS)}   /* per-frame easing factor, corrected for the real frame time */
function frame(ts){
  var dt=Math.min(.05,(ts-lastTs)/1000||0);lastTs=ts;DT=dt;FS=dt*60;
  if(!introDone){
    head=Math.min(N,(ts-t0)/1000*SPEED);
    EVS.forEach(function(e){if(!e.shown&&head>=e.i+1){e.shown=true;var el=chipEl(e.id);if(el)el.classList.add('on');}});
    if(follow)camX=clamp(xOf(head)-W*0.82,0,maxCam());
    if(head>=N){introDone=true;tDone=ts;stats();}
  }
  if(camTo!=null){camX+=(camTo-camX)*ez(.16);if(Math.abs(camTo-camX)<.5){camX=camTo;camTo=null;}}
  else if(Math.abs(vel)>.2){camX=clamp(camX+vel*FS,0,maxCam());vel*=Math.pow(.93,FS);}
  pinsEl.style.transform='translate3d('+(-camX)+'px,0,0)';
  draw(ts,dt);sky(dt);
  if(ts-lastRead>120||hoverI!==lastHover){readout();lastRead=ts;lastHover=hoverI;}
  requestAnimationFrame(frame);
}
function goTo(x,frac){follow=false;vel=0;camTo=clamp(x-W*(frac==null?.5:frac),0,maxCam());}

/* ---------- interaction ---------- */
var drag=null;
stage.addEventListener('pointerdown',function(e){
  if(e.target.closest('.chip'))return;
  drag={x:e.clientX,cam:camX,moved:false,lx:e.clientX,v:0,lt:e.timeStamp};follow=false;camTo=null;vel=0;
  stage.setPointerCapture(e.pointerId);stage.classList.add('drag');
});
stage.addEventListener('pointermove',function(e){
  var r=stage.getBoundingClientRect();
  if(drag){var dx=e.clientX-drag.x;if(Math.abs(dx)>4)drag.moved=true;camX=clamp(drag.cam-dx,0,maxCam());var dtm=Math.max(4,e.timeStamp-drag.lt);drag.v=(drag.lx-e.clientX)/dtm*16.7;drag.lx=e.clientX;drag.lt=e.timeStamp;hoverI=-1;return;}
  if(e.pointerType==='touch')return;
  var i=Math.floor((e.clientX-r.left+camX-PADL)/SLOT);hoverI=(i>=0&&i<N&&e.clientY-r.top>plotTop-20&&e.clientX-r.left<W-AXW)?i:-1;hovY=e.clientY-r.top;
  var hit=null,mx=e.clientX-r.left+camX,my=e.clientY-r.top;
  EVS.forEach(function(ev){if(ev.shown&&Math.abs(ev.x-mx)<12&&Math.abs(ev.y-my)<12)hit=ev.id;});
  setHover(hit);stage.style.cursor=hit?'pointer':'';
});
function endDrag(e){
  if(!drag)return;stage.classList.remove('drag');
  if(!drag.moved){var r=stage.getBoundingClientRect(),mx=e.clientX-r.left+camX,my=e.clientY-r.top,hit=null;
    EVS.forEach(function(ev){if(ev.shown&&Math.abs(ev.x-mx)<14&&Math.abs(ev.y-my)<14)hit=ev.id;});if(hit)openEvent(hit);}
  else vel=e.timeStamp-drag.lt<80?clamp(drag.v,-60,60):0;
  drag=null;
}
stage.addEventListener('pointerup',endDrag);stage.addEventListener('pointercancel',endDrag);
stage.addEventListener('pointerleave',function(){if(!drag){hoverI=-1;setHover(null);}});
stage.addEventListener('wheel',function(e){
  var d=Math.abs(e.deltaX)>Math.abs(e.deltaY)?e.deltaX:e.deltaY;if(!d)return;
  e.preventDefault();follow=false;camTo=null;camX=clamp(camX+d,0,maxCam());
},{passive:false});
stage.addEventListener('keydown',function(e){
  if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();goTo(camX+W/2+(e.key==='ArrowLeft'?-1:1)*W*0.4);}
});
function setHover(id){if(id===hovId)return;var o=hovId&&chipEl(hovId);if(o)o.classList.remove('hov');hovId=id;var n=id&&chipEl(id);if(n)n.classList.add('hov');}
pinsEl.addEventListener('click',function(e){var c=e.target.closest('.chip');if(c)openEvent(c.dataset.id);});
pinsEl.addEventListener('pointerover',function(e){var c=e.target.closest('.chip');setHover(c?c.dataset.id:null);});
