/* (22) three views: the time axis, the list of entries and the map. In the map view the chart stays where it is but fades into the background,
   and the world map with the news film moves from the background to the front (bigger, brighter, with its own controls). */
$('#viewsw').addEventListener('click',function(e){var b=e.target.closest('button');if(!b)return;var v=b.dataset.v,mo=document.querySelector('.monitor');listOn=v==='list';mapOn=v==='map';
  this.querySelectorAll('button').forEach(function(p){p.setAttribute('aria-pressed',p===b?'true':'false')});
  mo.classList.toggle('listv',listOn);mo.classList.toggle('mapv',mapOn);document.documentElement.classList.toggle('mapv',mapOn);$('#jlist').hidden=!listOn;$('#mapctl').hidden=!mapOn;
  if(listOn||mapOn)finishIntro();if(listOn)renderList();else resize();
  applyLook();TVE.hidden=true;tvCur=null;mapHov=-1;if(!mapOn)mo.style.paddingBottom='';document.body.style.cursor='';skySize();if(mapOn){if(!feed.length)worldShow(feedI%Math.max(1,WEV.length));mapNo();}});
$('#mapreg').addEventListener('click',function(e){var b=e.target.closest('.pill');if(!b)return;var g=VREG[b.dataset.r];if(g)mapView(g[0],g[1],g[2]);else mapView(0,11,360);});
function mapIn(e){return mapOn&&e.clientX>=WX&&e.clientX<=WX+WW&&e.clientY-MDY>=WY0&&e.clientY-MDY<=WY0+WH&&!e.target.closest('button,a,input,textarea,.drawer,.pop,.stk,.top');}
document.addEventListener('wheel',function(e){if(!mapIn(e))return;e.preventDefault();                    /* zoom around the pointer */
  var sp=VW.r-VW.l,ns=clamp(sp*Math.exp(clamp(e.deltaY,-120,120)*.0022),24,360),fx=(e.clientX-WX)/WW,fy=(e.clientY-MDY-WY0)/WH,lon=VW.l+fx*sp,lat=VW.t-fy*(VW.t-VW.b),nh=ns*138/360;
  mapView(lon-fx*ns+ns/2,lat+fy*nh-nh/2,ns);},{passive:false});
var mapDrag=null;
document.addEventListener('pointerdown',function(e){if(e.button||!mapIn(e)||!mapZoomed()||mapHit(e)>=0)return;mapDrag={x:e.clientX,y:e.clientY,l:VW.l,t:VW.t,s:VW.r-VW.l};});
document.addEventListener('pointermove',function(e){if(!mapDrag)return;var sp=mapDrag.s,hs=sp*138/360;mapView(mapDrag.l-(e.clientX-mapDrag.x)/WW*sp+sp/2,mapDrag.t+(e.clientY-mapDrag.y)/WH*hs-hs/2,sp);});
document.addEventListener('pointerup',function(){mapDrag=null;});document.addEventListener('pointercancel',function(){mapDrag=null;});
document.addEventListener('dblclick',function(e){if(mapIn(e)&&mapZoomed()){mapView(0,11,360);}});
$('#mapctl').addEventListener('click',function(e){var b=e.target.closest('.pill');if(!b||b.dataset.r!==undefined||!WEV.length)return;var m=b.dataset.m,cur=((feedI-1)%WEV.length+WEV.length)%WEV.length;
  if(m==='auto'){mapAuto=!mapAuto;b.setAttribute('aria-pressed',mapAuto?'true':'false');return;}
  worldShow(cur+(m==='next'?1:-1));});
$('#jlist').addEventListener('click',function(e){var c=e.target.closest('.je');if(c)openEvent(c.dataset.id);});
pfOn=look.pf!==false;$('#pfTog').setAttribute('aria-pressed',pfOn?'true':'false');$('#pfTog').addEventListener('click',function(){pfOn=!pfOn;this.setAttribute('aria-pressed',pfOn?'true':'false');look.pf=pfOn;try{localStorage.setItem(LKEY,JSON.stringify(look));}catch(er){}});
(function(){var h='';for(var y=Y0;y<=Y1;y++)h+='<button class="pill yr" data-y="'+y+'">'+y+'</button>';h+='<button class="pill yr" data-y="now">Teraz</button>';$('#years').innerHTML=h;})();
