  var g=c2.createLinearGradient(ex-60,0,ex+60,0);g.addColorStop(0,'rgba('+rgb+',0)');g.addColorStop(.5,'rgba('+rgb+',.22)');g.addColorStop(1,'rgba('+rgb+',0)');c2.fillStyle=g;c2.fillRect(ex-60,0,120,h);
  for(i=a;i<=b;i++){var k=C[i],x=(i-(e.i-18)+.5)*sl,up=k.c>=k.o;c2.globalAlpha=i===e.i?1:.6;c2.fillStyle=up?'#43c6a0':'#ea6b61';
    c2.fillRect(x-.6,yy(k.hi),1.2,yy(k.lo)-yy(k.hi));var t=Math.min(yy(k.o),yy(k.c)),hh=Math.max(3,Math.abs(yy(k.c)-yy(k.o)));rr(c2,x-sl*.32,t,sl*.64,hh,sl*.3);c2.fill();}
  c2.globalAlpha=1;var py=yy(C[e.i].c);
