var draft=null;
var ATT=[['vs','Wynik na tle rynku'],['px','Ceny BTC i ETH'],['era','Faza rynku']];   /* 134: bez danych trackera portfela */
function attInfo(k,iso){
  var t=Date.parse(iso+'T12:00:00Z');if(isNaN(t))return{ok:false,txt:'Najpierw wybierz datę.'};
  var tr=dayEnd(iso)>=HIST0,h0=HIST.length?fmtDate(isoOf(HIST0)):'',no={ok:false,txt:HIST.length?'Dostępne od '+h0+', wcześniej tracker nie ma historii.':'Brak historii trackera.'};
  if(k==='pf')return tr?{ok:true,txt:'Kwota z historii trackera dla tego dnia.'}:{ok:false,txt:(HIST.length?'Przed '+h0+' tracker nie ma historii. ':'')+'Wpisz kwotę niżej - wystarczy w przybliżeniu.'};
  if(k==='vs')return ACT&&dayEnd(iso)>=ACT0?{ok:true,txt:'Ty (z wpisanych kwot), BTC, ETH i indeks altów od startu cyklu do tego dnia.'}:{ok:false,txt:ACT?'Dostępne od startu aktywnego cyklu ('+fmtDate(isoOf(ACT0))+').':'Brak aktywnego cyklu.'};
  if(k==='wal')return tr?{ok:true,txt:'Wartość każdego portfela osobno.'}:no;
  if(k==='tx')return D.data&&Array.isArray(D.data.closedPositions)?{ok:true,txt:'Zamknięte pozycje sprzedane tego dnia, z wynikiem.'}:{ok:false,txt:'Brak danych trackera.'};
  if(k==='snap')return iso===TODAY&&D.data&&Array.isArray(D.data.assets)?{ok:true,txt:'Pięć największych pozycji z chwili dodania notatki.'}:{ok:false,txt:'Tylko dla dzisiejszej daty: tracker nie przechowuje dawnych pozycji.'};
  if(k==='px')return{ok:true,txt:'Kursy z dnia wydarzenia.'};
  return{ok:true,txt:eraAt(t).name+'.'};
}
/* (14) a past event (before the tracker's history): portfolio value typed by hand, roughly is fine; kept in the note (pf) like in the panel */
function pfField(iso){if(!iso||dayEnd(iso)>=HIST0)return '<div id="npfw"></div>';
  return '<div id="npfw"><label class="l" for="npf">Wartość portfela wtedy (w przybliżeniu)</label><div class="pf"><span class="num" style="color:var(--mut)">≈ $</span><input class="field num" id="npf" inputmode="numeric" maxlength="20" placeholder="np. 12 000"></div><div class="hint">Nie musi być dokładnie. Kwoty z kluczowych momentów tworzą złotą linię portfela na wykresie. Zmienisz ją później w panelu wydarzenia (Portfel wtedy).</div></div>';}
function attHtml(iso,checked){return ATT.map(function(a){var inf=attInfo(a[0],iso),on=inf.ok&&checked.indexOf(a[0])>=0;
  return '<label class="attc'+(inf.ok?'':' off')+'"><input type="checkbox" value="'+a[0]+'"'+(on?' checked':'')+(inf.ok?'':' disabled')+'><span><b>'+a[1]+'</b><small>'+esc(inf.txt)+'</small></span></label>'}).join('');}
/* the chosen tracker data is resolved once, at save time, and stored with the event */
function attResolve(keys,iso){var f=[],ms=dayEnd(iso),hp=histAt(ms);keys.forEach(function(k){if(!attInfo(k,iso).ok)return;
  if(k==='pf'&&hp)f.push(['Portfel',usd(hp.v)]);
  if(k==='vs')f=f.concat(vsMarket(ms));
  if(k==='wal'&&hp&&hp.w)Object.keys(hp.w).forEach(function(n){f.push([n,usd(hp.w[n])]);});
  if(k==='tx'){var cl=(D.data.closedPositions||[]).filter(function(c){return c.sellDate===iso});if(!cl.length)f.push(['Sprzedaże','brak tego dnia']);
    cl.slice(0,6).forEach(function(c){f.push(['Sprzedaż '+c.symbol,c.pnlUsd==null?'wynik nieznany':(c.pnlUsd>=0?'+':'−')+usd(Math.abs(c.pnlUsd))]);});}
  if(k==='snap')(D.data.assets||[]).slice().sort(function(a,b){return b.valueUsd-a.valueUsd}).slice(0,5).forEach(function(a){f.push([a.symbol,usd(a.valueUsd)]);});
  if(k==='px'){var pb=pxAt('btc',ms)||(REAL||iso>='2020-01-01'?C[wk(iso)].c*1000:null),pe=pxAt('eth',ms);if(pb)f.push(['BTC',usd(pb)]);if(pe)f.push(['ETH',usd(pe)]);}
  if(k==='era')f.push(['Faza rynku',eraAt(Date.parse(iso+'T12:00:00Z')).name]);});return f;}
function mdHtml(s){var out='',inl=false;String(s||'').split('\n').forEach(function(ln){var h=esc(ln).replace(/\*\*(.+?)\*\*/g,'<b>$1</b>');
  if(/^\s*- /.test(ln)){if(!inl){out+='<ul>';inl=true;}out+='<li>'+h.replace(/^\s*- /,'')+'</li>';}else{if(inl){out+='</ul>';inl=false;}out+=h+'<br>';}});
  if(inl)out+='</ul>';return out.replace(/(<br>)+$/,'');}
