function shotsHtml(a){return (a||[]).map(function(q,i){return '<div class="shot"><img src="'+esc(shotUrl(q.id))+'" loading="lazy" alt="Zrzut ekranu '+(i+1)+'" data-zoom="'+i+'"><button type="button" data-rm="'+i+'" aria-label="Usuń zrzut '+(i+1)+'">'+XS+'</button></div>'}).join('');}
function shotsBlock(a){return '';return '<div class="shots" id="shots">'+shotsHtml(a)+'</div><button type="button" class="drop" id="drop">Dodaj zrzut ekranu: kliknij, przeciągnij plik albo wklej (Ctrl+V)</button><input type="file" id="shotIn" accept="image/*" multiple hidden><div class="hint" id="shotMsg">Do 6 obrazów. Zapisują się razem z notatką i widać je na każdym urządzeniu.</div>';}
function shotList(make){if(draft)return draft.shots;var n=note();if(!n)return null;if(!n.shots&&make)n.shots=[];return n.shots||[];}
function shotsRefresh(msg){var b=$('#shots'),a=shotList(false);if(b)b.innerHTML=shotsHtml(a);var m=$('#shotMsg');if(m&&msg)m.textContent=msg;}
function addShots(files){
  var a=shotList(true),isDraft=!!draft;if(!a)return;
  [].slice.call(files).filter(function(f){return /^image\//.test(f.type)}).forEach(function(f){
    var rd=new FileReader();rd.onload=function(){var im=new Image();im.onload=function(){
      if(a.length>=6){shotsRefresh('Limit 6 obrazów na wydarzenie.');return;}
      var k=Math.min(1,1400/Math.max(im.width,im.height)),cv2=document.createElement('canvas');cv2.width=Math.round(im.width*k);cv2.height=Math.round(im.height*k);
      cv2.getContext('2d').drawImage(im,0,0,cv2.width,cv2.height);shotsRefresh('Wysyłam zrzut…');
      cv2.toBlob(function(blob){if(!blob){shotsRefresh('Nie udało się przygotować obrazu.');return;}
        putShot(blob).then(function(id){if(a.length>=6){delShot(id);return;}a.push({id:id,name:(f.name||'zrzut').slice(0,60)});if(!isDraft){save();afterSave();}shotsRefresh('Dodano.');})
          .catch(function(er){shotsRefresh('Nie udało się wysłać zrzutu: '+er.message);});},'image/jpeg',.82);};im.src=rd.result;};rd.readAsDataURL(f);});
}
