function saveCycles(){
  var out=[],bad='';drawer.querySelectorAll('#cyL .cyrow').forEach(function(r,i){
    var nm=r.querySelector('[data-cn]').value.trim(),st=r.querySelector('[data-cs]').value,en=r.querySelector('[data-ce]').value,sv=r.querySelector('[data-csv]').value,ev=r.querySelector('[data-cev]').value,no=r.querySelector('[data-cno]').value.trim();
    if(!nm&&!st&&!sv&&!en&&!ev&&!no)return;
    if(!/^\d{4}-\d{2}-\d{2}$/.test(st)){bad='Każdy cykl potrzebuje daty startu.';return;}
    if(en&&en<st){bad='Koniec cyklu „'+(nm||'bez nazwy')+'” jest przed startem.';return;}
    out.push({id:r.dataset.id||('c'+Date.now().toString(36)+i),name:(nm||'Cykl od '+fmtDate(st)).slice(0,40),startAt:st,startValue:cyNum(sv),endAt:en||null,endValue:en?cyNum(ev):null,note:no.slice(0,600)});});
  if(bad){$('#cyMsg').textContent=bad;return;}
  if(out.filter(function(c){return !c.endAt}).length>1){$('#cyMsg').textContent='Trwać może tylko jeden cykl naraz: wpisz koniec starszego.';return;}
  J.doc.cycles=out;saveJournal('cycles');loadCycles();closeDrawer();rebuild();
}
