  var up=e.target.closest('[data-upd]');if(up&&selId&&UPD[selId]){var nb=$('#updNew');if(up.dataset.upd==='show'){nb.hidden=false;nb.innerHTML='<b>Nowy opis:</b><br>'+mdHtml(UPD[selId].desc);}else{var sc=J.doc.seen[selId];sc.desc=UPD[selId].desc;sc.kind=UPD[selId].kind;delete UPD[selId];saveJournal('seen');var keep=selId;rebuild();openEvent(keep);}return;}
  var o=e.target.closest('.opt');if(!o)return;e.preventDefault();
