var stks=J.doc.stickies,stkBox=$('#stk');
function stkSave(){saveJournal('stickies');}
function stkPlace(el,q){var w=el.offsetWidth||176,h=el.offsetHeight||104;el.style.left=clamp(q.x*innerWidth,6,Math.max(6,innerWidth-w-6))+'px';el.style.top=clamp(q.y*innerHeight,60,Math.max(60,innerHeight-h-6))+'px';}
function stkEl(q){var el=document.createElement('div');el.className='stk';el.dataset.id=q.id;el.style.setProperty('--r',q.r+'deg');el.style.setProperty('--bt',(5+(q.id%5)*.6)+'s');
  el.innerHTML='<div class="stk-g"><span>Karteczka</span><button class="stk-x" aria-label="Usuń karteczkę">'+XS+'</button></div><textarea maxlength="160" placeholder="Szybka notatka…" aria-label="Treść karteczki"></textarea>';
  el.querySelector('textarea').value=q.t;stkBox.appendChild(el);stkPlace(el,q);return el;}
function stkFind(el){var id=+el.dataset.id;for(var i=0;i<stks.length;i++)if(stks[i].id===id)return i;return -1;}
stks.forEach(stkEl);
$('#stkAdd').addEventListener('click',function(){
  if(J.ro){askLogin('przyklejać karteczki');return;}
  if(stks.length>=8){this.textContent='Najwyżej 8';var b=this;setTimeout(function(){b.textContent='+ Karteczka'},1600);return;}
  var mo=document.querySelector('.monitor').getBoundingClientRect(),n=stks.length,y=Math.min(innerHeight-150,Math.max(70,mo.bottom+10)),
      q={id:Date.now(),t:'',x:(24+(n%6)*190+(n>5?60:0))/innerWidth,y:(y+(n>5?-40:0)+(n%2)*10)/innerHeight,r:[-1.6,1.2,-.8,1.8,-1.3,.9,-1.9,1.4][n%8]};
  if(innerWidth<700){q.x=(8+(n%2)*(innerWidth/2))/innerWidth;q.y=(innerHeight-116-Math.floor(n/2)%3*112)/innerHeight;}
  else if(q.x*innerWidth>innerWidth-190)q.x=(24+(n%2)*30)/innerWidth;
  stks.push(q);stkSave();stkEl(q).querySelector('textarea').focus();
});
stkBox.addEventListener('input',function(e){var el=e.target.closest('.stk'),i=el?stkFind(el):-1;if(i>=0){stks[i].t=e.target.value;stkSave();}});
stkBox.addEventListener('click',function(e){var x=e.target.closest('.stk-x');if(!x)return;var el=x.closest('.stk'),i=stkFind(el);if(i>=0){stks.splice(i,1);stkSave();}
  el.classList.add('sink');setTimeout(function(){el.remove()},reduced?0:650);});
var stkDrag=null;
stkBox.addEventListener('pointerdown',function(e){var g=e.target.closest('.stk-g');if(!g||e.target.closest('.stk-x'))return;var el=g.parentNode,r=el.getBoundingClientRect();
  stkDrag={el:el,dx:e.clientX-parseFloat(el.style.left),dy:e.clientY-parseFloat(el.style.top)};el.classList.add('drag');g.setPointerCapture(e.pointerId);e.preventDefault();});
stkBox.addEventListener('pointermove',function(e){if(!stkDrag)return;var el=stkDrag.el;el.style.left=clamp(e.clientX-stkDrag.dx,6,innerWidth-el.offsetWidth-6)+'px';el.style.top=clamp(e.clientY-stkDrag.dy,60,innerHeight-el.offsetHeight-6)+'px';});
function stkDrop(){if(!stkDrag)return;var el=stkDrag.el,i=stkFind(el);el.classList.remove('drag');if(i>=0){stks[i].x=parseFloat(el.style.left)/innerWidth;stks[i].y=parseFloat(el.style.top)/innerHeight;stkSave();}stkDrag=null;}
stkBox.addEventListener('pointerup',stkDrop);stkBox.addEventListener('pointercancel',stkDrop);
window.addEventListener('resize',function(){stkBox.querySelectorAll('.stk').forEach(function(el){var i=stkFind(el);if(i>=0)stkPlace(el,stks[i]);});});

