/* ---------- loading (134): dane z galezi data / ema, dziennik z konta ---------- */
setStoreHooks({
  onStatus:function(kind,msg){var s=$('#saved'),f=$('#jstat');var t=kind==='saved'?'Zapisano '+new Date().toLocaleTimeString('pl-PL').slice(0,5):kind==='error'?'Nie zapisano: '+msg:'Zapisuję…';
    if(s)s.textContent=t;if(f){f.textContent=kind==='error'?t:'';f.hidden=kind!=='error';}}
});
var QS=new URLSearchParams(location.search);
function branchBase(param,branch,local){
  if(QS.get(param))return QS.get(param).replace(/\/?$/,'/');
  if(location.hostname.endsWith('github.io')){var owner=location.hostname.split('.')[0],repo=location.pathname.split('/').filter(Boolean)[0]||'';return 'https://raw.githubusercontent.com/'+owner+'/'+repo+'/'+branch+'/';}
  return (local||branch)+'/';
}
var DATA_BASE=branchBase('data','data'),EMA_BASE=branchBase('ema','ema','ema-data');
function getJSON(url){return fetch(url+(url.indexOf('?')<0?'?':'&')+'v='+Math.floor(Date.now()/300000),{cache:'no-cache'}).then(function(r){if(!r.ok)throw new Error(url.split('/').pop()+': HTTP '+r.status);return r.json();})}
function opt(p){return p.then(function(x){return x},function(){return null})}
/* to samo co build-market.mjs w apce portfela: tygodniowe swiece BTC (poniedzialek UTC) z dziennych Binance (hist/BTC.json),
   przed 08.2017 swiece Bitstampa (btc-weekly-early.json); wydarzenia (history_events) i fazy cyklu (cycle_marks) z meta.json */
function buildJournal(meta,btc,early){
  var DAY=86400,WEEK=7*DAY,MON=4*DAY;if(!btc||!Array.isArray(btc.d)||btc.d.length<=30)return null;
  var r6=function(v){return Math.round(v*1e6)/1e6},weeks=new Map(),prev=null;
  btc.d.forEach(function(row){var t=row[0],c=row[1];if(!isFinite(t)||!(c>0))return;var hi=row[3]>0?row[3]:c,lo=row[4]>0?row[4]:c,ws=Math.floor((t-MON)/WEEK)*WEEK+MON,w=weeks.get(ws);
    if(!w){w={o:prev===null?c:prev,h:-Infinity,l:Infinity,c:c};weeks.set(ws,w);}w.h=Math.max(w.h,hi,w.o);w.l=Math.min(w.l,lo,w.o);w.c=c;prev=c;});
  if(early&&Array.isArray(early.c)){var s0=Math.min.apply(null,Array.from(weeks.keys())),lastT=null;
    for(var i=0;i<early.c.length;i++){var t=early.t0+i*WEEK;if(t>s0||!(early.c[i]>0))continue;weeks.set(t,{o:early.o[i],h:early.h[i],l:early.l[i],c:early.c[i]});lastT=t;}
    var nx=lastT!==null?weeks.get(lastT+WEEK):null;if(nx){nx.o=weeks.get(lastT).c;nx.h=Math.max(nx.h,nx.o);nx.l=Math.min(nx.l,nx.o);}}
  var keys=Array.from(weeks.keys()).sort(function(a,b){return a-b}),w0=keys[0],w1=keys[keys.length-1],wk={t0:w0,step:WEEK,o:[],h:[],l:[],c:[]},last=weeks.get(w0);
  for(var tt=w0;tt<=w1;tt+=WEEK){var w=weeks.get(tt)||{o:last.c,h:last.c,l:last.c,c:last.c};wk.o.push(r6(w.o));wk.h.push(r6(w.h));wk.l.push(r6(w.l));wk.c.push(r6(w.c));last=w;}
  var str=function(v,n){return String(v===null||v===undefined?'':v).slice(0,n)};
  var events=(meta&&Array.isArray(meta.history_events)?meta.history_events:[]).filter(function(e){return e&&/^\d{4}-\d{2}-\d{2}$/.test(String(e.date))&&e.label}).map(function(e){
    var o={date:e.date,label:str(e.label,80),desc:str(e.desc,600),kind:str(e.kind,20)};
    if(e.lon!==undefined&&e.lat!==undefined&&isFinite(Number(e.lon))&&isFinite(Number(e.lat))&&Math.abs(Number(e.lat))<=90&&Math.abs(Number(e.lon))<=180){o.lon=Number(e.lon);o.lat=Number(e.lat);}return o;});
  var cm=meta&&meta.cycle_marks||{};
  var phases=(Array.isArray(cm.phases)?cm.phases:[]).filter(function(p){return p&&isFinite(p.from)&&(p.to===null||p.to===undefined||p.to>w0)}).map(function(p){
    var o={phase:str(p.phase,10),from:p.from,to:isFinite(p.to)&&p.to!==null?p.to:null};if(p.confirmed===false)o.open=true;return o;});
  var marks=(Array.isArray(cm.events)?cm.events:[]).filter(function(e){return e&&isFinite(e.t)&&e.t>=w0}).map(function(e){var o={t:e.t,kind:str(e.kind,12),label:str(e.label,60)};if(e.value>0)o.value=r6(e.value);return o;});
  return {wk:wk,events:events,phases:phases,marks:marks};
}
/* dzienne zamkniecia jako siatka {t0, step, nazwa:[...]} - czyta ja gridAt (ceny BTC / ETH, indeks altow) */
function dayGrid(rows,name){if(!rows||!rows.length)return null;var t0=rows[0][0],g={t0:t0,step:86400};g[name]=[];rows.forEach(function(r){var i=Math.round((r[0]-t0)/86400);if(i>=0)g[name][i]=r[1]>0?r[1]:0;});
  for(var k=0;k<g[name].length;k++)if(g[name][k]===undefined)g[name][k]=0;return g}
Promise.all([loadJournal(),opt(getJSON(DATA_BASE+'meta.json')),opt(getJSON(EMA_BASE+'hist/BTC.json')),opt(getJSON(EMA_BASE+'hist/ETH.json')),opt(getJSON(EMA_BASE+'altindex.json')),opt(getJSON('dziennik/btc-weekly-early.json'))]).then(function(r){
  var meta=r[1],btc=r[2],eth=r[3],alt=r[4],market={journal:buildJournal(meta,btc,r[5])};
  var gb=btc&&dayGrid(btc.d,'btc'),ge=eth&&dayGrid(eth.d,'eth');
  if(gb&&ge){var h={t0:Math.min(gb.t0,ge.t0),step:86400,btc:[],eth:[]};[[gb,'btc'],[ge,'eth']].forEach(function(q){var off=Math.round((q[0].t0-h.t0)/86400);for(var i=0;i<off;i++)h[q[1]].push(0);h[q[1]]=h[q[1]].concat(q[0][q[1]]);});market.h=h;}
  if(alt&&Array.isArray(alt.d))market.alt=dayGrid(alt.d,'v');
  $('#boot').hidden=true;start({market:market,history:[],data:null});
}).catch(function(e){var b=$('#boot');b.textContent='Nie udało się wczytać dziennika: '+(e&&(e.code||e.message))+'. Odśwież stronę.';});
